document.getElementById('googleLoginBtn').addEventListener('click',function(){const provider=new firebase.auth.GoogleAuthProvider();firebase .auth().signInWithPopup(provider).then(result=>{const userTemp=result.user;localStorage.setItem('user',JSON.stringify(userTemp));redirectToDashboard();}).catch(error=>{console.error('Error during Google login:',error.message);alert('Google login failed: '+error.message);});});